            "experimental_lexical_semantics": "identifier-expansion-v1",
            "path_or_package_scoring": False,
        },
        "aggregate": {
            "baseline": _summary_payload(summary=baseline_summary),
            "experimental": experimental_metrics,
            "delta": {
                key: experimental_metrics[key]
